#include "runtime_short_kernel.hpp"
#include <fcntl.h>
#include <sys/stat.h>
int main(int argc,char**argv){if(argc!=2)return 2;int fd=open(argv[1],O_RDONLY);struct stat st;fstat(fd,&st);auto*m=(const unsigned char*)mmap(nullptr,st.st_size,PROT_READ,MAP_PRIVATE,fd,0);uint32_t h[6];std::memcpy(h,m+72,24);size_t geometries=size_t(h[2])*h[3];auto*p=m+96+h[2]*2;std::array<uint64_t,17>counts{};std::array<int16_t,160*160>a;std::array<int16_t,160>bias;int maxspan=0,maximum=0;for(size_t g=0;g<geometries;++g){bias.fill(INT16_MAX);for(unsigned s=0;s<160;++s)for(unsigned t=0;t<160;++t){int16_t v=RuntimeShortKernel::View::raw(p+(g*160+s)*220,t);a[s*160+t]=v;bias[t]=std::min(bias[t],v);}for(unsigned s=0;s<160;++s){int lo=INT_MAX,hi=INT_MIN;for(unsigned t=0;t<160;++t){int v=a[s*160+t]-bias[t];lo=std::min(lo,v);hi=std::max(hi,v);maximum=std::max(maximum,v);}unsigned span=hi-lo,b=1;while((1u<<b)<=span)++b;++counts[b];maxspan=std::max(maxspan,int(span));}}std::cout<<"geometries="<<geometries<<" max_span="<<maxspan<<" global_min=0 global_max="<<maximum<<'\n';for(unsigned b=0;b<17;++b)if(counts[b])std::cout<<"bits="<<b<<" rows="<<counts[b]<<'\n';}
